class Cart {
    // Every new discount type edits this method and retests every branch.
    double checkout(double price, String discountType) {
        if (discountType.equals("NONE"))         return price;
        else if (discountType.equals("STUDENT"))  return price * 0.85; // 15% off
        else if (discountType.equals("BLACK_FRIDAY")) return price * 0.50;
        // add "FESTIVE"? edit here, risk breaking STUDENT and BLACK_FRIDAY
        else throw new IllegalArgumentException("Unknown: " + discountType);
    }
}
