```java
// Strategy interface
interface PaymentStrategy { boolean process(double amount, Map<String,String> details); }

@Component("card")
class CreditCardPayment implements PaymentStrategy {
    public boolean process(double amount, Map<String,String> d) {
        return d.get("cvv") != null && d.get("cvv").length() == 3; // validate + charge
    }
}

@Component("upi")
class UPIPayment implements PaymentStrategy {
    public boolean process(double amount, Map<String,String> d) {
        return d.getOrDefault("vpa", "").contains("@"); // verify VPA
    }
}

@Service
class PaymentService {
    private final Map<String, PaymentStrategy> strategies; // Spring fills by bean name
    PaymentService(Map<String, PaymentStrategy> strategies) { this.strategies = strategies; }

    boolean checkout(String type, double amount, Map<String,String> details) {
        var strategy = strategies.get(type);          // lookup, not if-else
        if (strategy == null) throw new IllegalArgumentException("Unknown: " + type);
        return strategy.process(amount, details);     // delegate blindly
    }
}
// Add WalletPayment with @Component("wallet") — map grows, service untouched.
```

*Spring injects every `PaymentStrategy` bean into the map keyed by bean name, so the only conditional left is a clean map lookup.*

