abstract class PaymentProcessor { abstract boolean process(double amount); }
class CreditCardProcessor extends PaymentProcessor {
    boolean process(double amount) { /* card logic */ return true; }
}
// Behavior is fixed when you instantiate:
PaymentProcessor p = new CreditCardProcessor();
// p can NEVER process UPI. Need card + fraud check + loyalty?
// -> CreditCardWithFraud, CreditCardWithFraudAndLoyalty, UpiWithFraud...
// N behaviors x M add-ons = combinatorial subclass explosion.
