```java
interface PaymentStrategy { boolean process(double amount); }
class CreditCard implements PaymentStrategy { public boolean process(double a){ return true; } }
class Upi        implements PaymentStrategy { public boolean process(double a){ return true; } }

// A decorator strategy adds fraud checking to ANY strategy — no new subclass per combo
class FraudChecked implements PaymentStrategy {
    private final PaymentStrategy delegate;
    FraudChecked(PaymentStrategy delegate) { this.delegate = delegate; }
    public boolean process(double a) { return a < 10000 && delegate.process(a); }
}

class PaymentService {
    private PaymentStrategy strategy;            // HAS-A
    void setStrategy(PaymentStrategy s) { this.strategy = s; } // swap at runtime
    boolean checkout(double a) { return strategy.process(a); }
}

var svc = new PaymentService();
svc.setStrategy(new FraudChecked(new CreditCard())); // compose, don't subclass
svc.setStrategy(new Upi());                          // swap at runtime
```

*One context, behaviors injected and composed — no hierarchy to grow.*
